/**
 * Opt-in support bundle preview (DIAG-002).
 *
 * The bundle is built only when the user asks for it, shown in full
 * before anything leaves the page, and copied only by an explicit Copy
 * action. Veyora never uploads it and contains no automatic submission
 * path by construction: the only affordance here is a clipboard copy.
 * Bundle text is generated by data/diagnostics.js from the DIAG-001
 * safe sources only.
 */
import { t } from '../i18n/index.js';
import { icon } from '../core/icons.js';
import { $, toast, captureFocusReturn } from '../core/ui.js';
import { serviceHealth, buildSupportBundle } from '../data/diagnostics.js';

/** Markup for the preview overlay, mounted by the dashboard shell so
 *  locale re-renders rebuild it with the rest of the surface. */
export function supportBundleOverlayHtml() {
  return `
    <div class="modal modal-sm">
      <div class="modal-head">
        <h2 id="bundle-title">${t('diag.bundleTitle')}</h2>
        <button class="btn-icon" data-close title="${t('common.close')}"
                aria-label="${t('common.close')}">${icon('x', 15)}</button>
      </div>
      <div class="modal-body">
        <p class="micro">${t('diag.bundleIntro')}</p>
        <pre class="d-pre" id="bundle-text" data-testid="support-bundle"
             style="white-space:pre-wrap;font-family:var(--font-mono);font-size:var(--type-scale-5)"></pre>
      </div>
      <div class="modal-foot">
        <button class="btn" data-close>${t('common.close')}</button>
        <button class="btn btn-primary" id="btn-copy-bundle">${icon('copy', 14)}${t('diag.bundleCopy')}</button>
      </div>
    </div>`;
}

/** Open the preview with a fresh health probe (idempotent). */
export function openSupportBundle() {
  const overlay = $('#ov-bundle');
  if (!overlay) return;
  serviceHealth().then(health => {
    const host = $('#bundle-text');
    if (host) host.textContent = buildSupportBundle(health);
  });
  captureFocusReturn(overlay);
  overlay.classList.add('on');
  setTimeout(() => $('#btn-copy-bundle').focus(), 60);
}

/**
 * Install document-level delegation for the copy action. Delegation
 * survives dashboard re-renders (theme, locale) without rebinding.
 */
export function installSupportBundleDelegation() {
  document.addEventListener('click', async event => {
    if (!event.target.closest('#btn-copy-bundle')) return;
    const text = $('#bundle-text')?.textContent || '';
    if (!text) return;
    // Deliberately not copyWithTimeout: a bundle copy must not advance the
    // Start-here checklist or emit a first-success secret event, and the
    // text contains no secret that needs a clipboard-clear window.
    try {
      await navigator.clipboard.writeText(text);
      toast(t('diag.bundleCopied'), 'copy');
    } catch {
      toast(t('toast.copyFail'), 'alert');
    }
  });
}
